/**
 * XERP Office Editor: Default empty document templates.
 * Defaults configured to standard Arial / Latin font scheme, avoiding Chinese 等线 (DengXian).
 * Preserves binary compatibility with ONLYOFFICE x2t / sdkjs Editor.bin.
 */

function decodeBase64(b64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(b64, "base64"));
  }
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes;
}

export const emptyDocx: Uint8Array = decodeBase64(
  ""
);

export const emptyXlsx: Uint8Array = decodeBase64(
  ""
);

export const emptyPptx: Uint8Array = decodeBase64(
  ""
);

